-- Finance register import: register-it. Generated by register_import.py from register-it-plan.csv.
-- "fill" rows add the register cost, dates, bill and party to existing assets where blank.
-- "new" rows create the asset; a named holder gets it as "not yet confirmed". No emails or notifications.
-- Refuses to run twice.
\set ON_ERROR_STOP on
BEGIN;
-- The database checks every category, subcategory, status, condition, location and department
-- this file sets (migration 065); a missing or switched-off value stops the whole file.
SET LOCAL iac.strict_links = 'on';
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM audit_events WHERE action = 'REGISTER_IMPORTED' AND changes->>'tag' = 'register-it') THEN
    RAISE EXCEPTION 'register-it was already imported.';
  END IF;
END $$;
CREATE TEMP TABLE importer ON COMMIT DROP AS
  SELECT ur.user_id AS id FROM user_roles ur WHERE ur.role_code='SUPER_ADMIN' ORDER BY ur.granted_at LIMIT 1;
CREATE TEMP TABLE reg (n int PRIMARY KEY, action text, asset_code text, team text, category text, asset_type text,
  description text, model text, serial text, cost numeric, bought date, capitalised date, bill text, party text,
  status text, condition text, location_code text, holder text, note text, meta jsonb, configuration text,
  manufacturer text, asset_id uuid, holder_id uuid) ON COMMIT DROP;
